                    cp.move(so, sd)
                    after_bad = cp.bad()
                    after_sorted = cp.sorted_n[sd]
                    after_ub = cp.ub(sd)
                    dest_height = cp.h(sd)
                    src_height = cp.h(so)
                    dest_top = cp.g(sd)
                except Exception:
