class GuardedGoodPlaceTransitions:
    def __init__(self, rule_name: str, min_safe_destinations: int = 2, prefer_empty_gap: int = 1, use_rule_min_bad: int = 1):
        self.rule_name = rule_name
        self.min_safe_destinations = int(min_safe_destinations)
        self.prefer_empty_gap = int(prefer_empty_gap)
        self.use_rule_min_bad = int(use_rule_min_bad)

    def initial(self, partial):
        return ()

    def _count_safe_destinations(self, partial):
        count = 0
        for sd in range(partial.S):
            if len(partial.stacks[sd]) >= partial.H:
                continue
            if partial.is_sorted_stack(sd):
                count += 1
        return count

    def _has_clear_progress(self, partial):
        # Heurística de transición: usar la regla solo cuando hay suficiente estructura
        # para que su orden local tenga sentido; en estados muy abiertos o casi sin
        # destinos "seguros", dejar que el respaldo elija.
        if partial.bad() <= self.use_rule_min_bad:
            return True
        safe = self._count_safe_destinations(partial)
        if safe >= self.min_safe_destinations:
            return True
        empty_stacks = 0
        for s in partial.stacks:
            if not s:
                empty_stacks += 1
        if empty_stacks > self.prefer_empty_gap:
            return False
        # Si la mayoría de las pilas ya tienen al menos un bloque ordenado, la regla
        # suele ser útil; en caso contrario, el fallback evita decisiones codiciosas
        # demasiado rígidas.
        sorted_nonempty = 0
        nonempty = 0
        for i in range(partial.S):
            if partial.stacks[i]:
                nonempty += 1
                if partial.is_sorted_stack(i):
                    sorted_nonempty += 1
        if nonempty == 0:
            return False
        return sorted_nonempty * 2 >= nonempty

    def select(self, partial, memory, rules):
        if rules.active == self.rule_name and not rules.done(self.rule_name):
            return (self.rule_name, memory)
        if rules.applies(self.rule_name) and self._has_clear_progress(partial):
            return (self.rule_name, memory)
        return (FALLBACK, memory)


